* >Natural Source Code: PRODENTR
* PROGRAM: PRODENTR - PRODUCT ENTRY (ONLINE)
* DESCRIPTION: INTERACTIVE PRODUCT CREATION AND
*              MAINTENANCE SCREEN
* LIBRARY: RETAILCORE
* ADABAS FILE: 101 (PRODUCT)
* CREATED: 1998-07-01  T. ANDERSON
* MODIFIED: 2004-02-15 - ADDED WEB FIELDS
* MODIFIED: 2011-09-20 - ADDED PRODUCT DIMENSIONS
* MODIFIED: 2018-05-14 - ADDED CLEARANCE HANDLING
* MODIFIED: 2023-01-20 - ADDED SUSTAINABILITY FIELDS
* -------------------------------------------------------
DEFINE DATA
LOCAL USING PROD-COPY
LOCAL USING COMMON-COPY
LOCAL USING ERROR-COPY
*
LOCAL
  1 #ACTION               (A1)    /* A=ADD U=UPDATE D=DISPLAY */
  1 #SCREEN-MSG           (A78)
  1 #SCREEN-MSG-ATTR      (C)
  1 #VALID-FLAG           (A1)
  1 #ERROR-MSG            (A60)
  1 #NEW-PROD-ID          (N8)
  1 #SEARCH-PROD-ID       (N8)
  1 #SEARCH-SKU           (A15)
  1 #USER-ID              (A8)
  1 #PROD-ID-STR          (A15)
*
* ADABAS FILE 101 - PRODUCT
  1 PROD-VIEW VIEW OF PRODUCT-FILE
    2 PR-ID                (N8)
    2 PR-SKU               (A15)
    2 PR-NAME              (A60)
    2 PR-SHORT-DESC        (A30)
    2 PR-LONG-DESC         (A200)
    2 PR-STATUS            (A1)
    2 PR-TYPE              (A2)
    2 PR-BRAND             (A30)
    2 PR-MANUFACTURER      (A40)
    2 PR-UPC               (A13)
    2 PR-DEPT              (A4)
    2 PR-CLASS             (A4)
    2 PR-SUBCLASS          (A4)
    2 PR-COLOR             (A20)
    2 PR-SIZE              (A10)
    2 PR-WEIGHT            (N7.3)
    2 PR-BASE-COST         (N9.2)
    2 PR-BASE-PRICE        (N9.2)
    2 PR-MSRP              (N9.2)
    2 PR-MIN-PRICE         (N9.2)
    2 PR-TAX-CODE          (A4)
    2 PR-CURRENCY          (A3)
    2 PR-WEB-ENABLED       (A1)
    2 PR-PERISHABLE        (A1)
    2 PR-HAZARDOUS         (A1)
    2 PR-SEASONAL          (A1)
    2 PR-SEASON-CODE       (A4)
    2 PR-PRIMARY-SUPP      (N6)
    2 PR-LEAD-TIME         (N3)
    2 PR-MIN-ORDER-QTY     (N6)
    2 PR-REORDER-QTY       (N6)
    2 PR-INTRO-DATE        (D)
    2 PR-CREATED-DATE      (D)
    2 PR-CREATED-BY        (A8)
    2 PR-MODIFIED-DATE     (D)
    2 PR-MODIFIED-BY       (A8)
END-DEFINE
*
* -------------------------------------------------------
* MAIN PROCESSING LOOP
* -------------------------------------------------------
MOVE *USER TO #USER-ID
*
REPEAT
  INPUT (IP=ON) WITH TEXT #SCREEN-MSG
    / 'RETAILCORE - PRODUCT MAINTENANCE' (I)
    / '================================' (I)
    /
    / 'ACTION     :' #ACTION (AD=MI) '  (A=ADD U=UPDATE D=DISPLAY)'
    / 'PRODUCT ID :' #SEARCH-PROD-ID (AD=MI)
    / 'SKU        :' #SEARCH-SKU (AD=MI)
    /
    / 'PF3=EXIT  ENTER=PROCESS'
*
  IF *PF-KEY = 'PF3'
    ESCAPE BOTTOM
  END-IF
*
  RESET #SCREEN-MSG
*
  DECIDE ON FIRST VALUE OF #ACTION
    VALUE 'A'
      PERFORM ADD-PRODUCT
    VALUE 'U'
      PERFORM UPDATE-PRODUCT
    VALUE 'D'
      PERFORM DISPLAY-PRODUCT
    NONE VALUE
      MOVE 'INVALID ACTION' TO #SCREEN-MSG
  END-DECIDE
*
END-REPEAT
*
* =======================================
* ADD PRODUCT SUBROUTINE
* =======================================
DEFINE SUBROUTINE ADD-PRODUCT
  RESET PRODUCT-DATA
  RESET PRODUCT-CATEGORY
  RESET PRODUCT-ATTRIBUTES
  RESET PRODUCT-PRICE-REF
*
  INPUT (IP=ON) WITH TEXT #SCREEN-MSG
    / 'RETAILCORE - ADD NEW PRODUCT' (I)
    / '============================' (I)
    /
    / 'SKU          :' PROD-SKU (AD=MI)
    / 'NAME         :' PROD-NAME (AD=MI)
    / 'SHORT DESC   :' PROD-SHORT-DESC (AD=MI)
    / 'TYPE         :' PROD-TYPE (AD=MI) '  (PH=PHYSICAL DG=DIGITAL SV=SERVICE)'
    / 'BRAND        :' PROD-BRAND (AD=MI)
    / 'MANUFACTURER :' PROD-MANUFACTURER (AD=MI)
    / 'UPC          :' PROD-UPC (AD=MI)
    /
    / '--- CATEGORY ---'
    / 'DEPARTMENT   :' PROD-DEPT (AD=MI)
    / 'CLASS        :' PROD-CLASS (AD=MI)
    / 'SUBCLASS     :' PROD-SUBCLASS (AD=MI)
    /
    / '--- ATTRIBUTES ---'
    / 'COLOR        :' PROD-COLOR (AD=MI)
    / 'SIZE         :' PROD-SIZE (AD=MI)
    / 'WEIGHT (KG)  :' PROD-WEIGHT (AD=MI)
    / 'PERISHABLE   :' PROD-PERISHABLE (AD=MI) '(Y/N)'
    / 'HAZARDOUS    :' PROD-HAZARDOUS (AD=MI) '(Y/N)'
    / 'SEASONAL     :' PROD-SEASONAL (AD=MI) '(Y/N)'
    /
    / '--- PRICING ---'
    / 'BASE COST    :' PROD-BASE-COST (AD=MI)
    / 'BASE PRICE   :' PROD-BASE-PRICE (AD=MI)
    / 'MSRP         :' PROD-MSRP (AD=MI)
    / 'MIN PRICE    :' PROD-MIN-PRICE (AD=MI)
    / 'TAX CODE     :' PROD-TAX-CODE (AD=MI)
    /
    / '--- SUPPLIER ---'
    / 'PRIMARY SUPP :' PROD-PRIMARY-SUPP (AD=MI)
    / 'LEAD TIME    :' PROD-LEAD-TIME (AD=MI) 'DAYS'
    / 'REORDER QTY  :' PROD-REORDER-QTY (AD=MI)
    /
    / 'WEB ENABLED  :' PROD-WEB-ENABLED (AD=MI) '(Y/N)'
    /
    / 'PF3=CANCEL  ENTER=SAVE'
*
  IF *PF-KEY = 'PF3'
    MOVE 'ADD CANCELLED' TO #SCREEN-MSG
    ESCAPE ROUTINE
  END-IF
*
  * VALIDATE
  CALLNAT 'PRODVAL'
    PRODUCT-DATA
    PRODUCT-CATEGORY
    PRODUCT-ATTRIBUTES
    PRODUCT-PRICE-REF
    #VALID-FLAG
    #ERROR-MSG
*
  IF #VALID-FLAG NE 'Y'
    MOVE #ERROR-MSG TO #SCREEN-MSG
    ESCAPE ROUTINE
  END-IF
*
  * GENERATE PRODUCT ID
  CALLNAT 'SEQNON' 'PROD' #NEW-PROD-ID
*
  STORE PROD-VIEW
    PR-ID           := #NEW-PROD-ID
    PR-SKU          := PROD-SKU
    PR-NAME         := PROD-NAME
    PR-SHORT-DESC   := PROD-SHORT-DESC
    PR-STATUS       := 'A'
    PR-TYPE         := PROD-TYPE
    PR-BRAND        := PROD-BRAND
    PR-MANUFACTURER := PROD-MANUFACTURER
    PR-UPC          := PROD-UPC
    PR-DEPT         := PROD-DEPT
    PR-CLASS        := PROD-CLASS
    PR-SUBCLASS     := PROD-SUBCLASS
    PR-COLOR        := PROD-COLOR
    PR-SIZE         := PROD-SIZE
    PR-WEIGHT       := PROD-WEIGHT
    PR-BASE-COST    := PROD-BASE-COST
    PR-BASE-PRICE   := PROD-BASE-PRICE
    PR-MSRP         := PROD-MSRP
    PR-MIN-PRICE    := PROD-MIN-PRICE
    PR-TAX-CODE     := PROD-TAX-CODE
    PR-CURRENCY     := 'USD'
    PR-WEB-ENABLED  := PROD-WEB-ENABLED
    PR-PERISHABLE   := PROD-PERISHABLE
    PR-HAZARDOUS    := PROD-HAZARDOUS
    PR-SEASONAL     := PROD-SEASONAL
    PR-PRIMARY-SUPP := PROD-PRIMARY-SUPP
    PR-LEAD-TIME    := PROD-LEAD-TIME
    PR-REORDER-QTY  := PROD-REORDER-QTY
    PR-INTRO-DATE   := *DATX
    PR-CREATED-DATE := *DATX
    PR-CREATED-BY   := #USER-ID
    PR-MODIFIED-DATE := *DATX
    PR-MODIFIED-BY  := #USER-ID
  END-STORE
*
  ON ERROR
    COMPRESS 'DATABASE ERROR ON PRODUCT ADD:' *ERROR-NR INTO #SCREEN-MSG
    CALLNAT 'LOGERR' ERR-PROD-DUPLICATE 'PRODUCT ADD FAILED'
      'E' 'PRODENTR' #USER-ID
    ESCAPE ROUTINE
  END-ERROR
*
  END OF TRANSACTION
*
  MOVE #NEW-PROD-ID TO #PROD-ID-STR
  CALLNAT 'AUDITN' 'PROD' #PROD-ID-STR 'C' 'PRODUCT'
    ' ' PROD-NAME 'NEW PRODUCT CREATED'
*
  COMPRESS 'PRODUCT' #NEW-PROD-ID 'CREATED - SKU:' PROD-SKU
    INTO #SCREEN-MSG
*
END-SUBROUTINE
*
* =======================================
* UPDATE PRODUCT SUBROUTINE
* =======================================
DEFINE SUBROUTINE UPDATE-PRODUCT
*
  IF #SEARCH-PROD-ID = 0 AND #SEARCH-SKU = ' '
    MOVE 'ENTER PRODUCT ID OR SKU' TO #SCREEN-MSG
    ESCAPE ROUTINE
  END-IF
*
  CALLNAT 'PRODGET'
    #SEARCH-PROD-ID
    #SEARCH-SKU
    PRODUCT-DATA
    PRODUCT-CATEGORY
    PRODUCT-ATTRIBUTES
    PRODUCT-PRICE-REF
    PRODUCT-LIFECYCLE
    #VALID-FLAG
    #ERROR-MSG
*
  IF #VALID-FLAG NE 'Y'
    MOVE #ERROR-MSG TO #SCREEN-MSG
    ESCAPE ROUTINE
  END-IF
*
  * SIMPLIFIED - DISPLAY FOR UPDATE AND PROCESS
  INPUT (IP=ON)
    / 'RETAILCORE - UPDATE PRODUCT' (I)
    / 'ID  :' PROD-ID (AD=OI) 'SKU:' PROD-SKU (AD=OI)
    / 'NAME:' PROD-NAME (AD=MI)
    / 'STATUS   :' PROD-STATUS (AD=MI) '(A=ACTIVE I=INACTIVE D=DISCO C=CLEAR)'
    / 'BASE COST:' PROD-BASE-COST (AD=MI)
    / 'BASE PRICE:' PROD-BASE-PRICE (AD=MI)
    / 'WEB      :' PROD-WEB-ENABLED (AD=MI)
    / 'PF3=CANCEL ENTER=SAVE'
*
  IF *PF-KEY = 'PF3'
    ESCAPE ROUTINE
  END-IF
*
  CALLNAT 'PRODUPD'
    PROD-ID PROD-NAME PROD-STATUS PROD-BASE-COST
    PROD-BASE-PRICE PROD-WEB-ENABLED
    #VALID-FLAG #ERROR-MSG
*
  IF #VALID-FLAG = 'Y'
    COMPRESS 'PRODUCT' PROD-ID 'UPDATED' INTO #SCREEN-MSG
  ELSE
    MOVE #ERROR-MSG TO #SCREEN-MSG
  END-IF
*
END-SUBROUTINE
*
* =======================================
* DISPLAY PRODUCT SUBROUTINE
* =======================================
DEFINE SUBROUTINE DISPLAY-PRODUCT
*
  CALLNAT 'PRODGET'
    #SEARCH-PROD-ID #SEARCH-SKU
    PRODUCT-DATA PRODUCT-CATEGORY PRODUCT-ATTRIBUTES
    PRODUCT-PRICE-REF PRODUCT-LIFECYCLE
    #VALID-FLAG #ERROR-MSG
*
  IF #VALID-FLAG NE 'Y'
    MOVE #ERROR-MSG TO #SCREEN-MSG
    ESCAPE ROUTINE
  END-IF
*
  INPUT (IP=ON)
    / 'RETAILCORE - PRODUCT DISPLAY' (I)
    / 'PRODUCT ID :' PROD-ID (AD=OI) 'SKU:' PROD-SKU (AD=OI)
    / 'NAME       :' PROD-NAME (AD=OI)
    / 'STATUS     :' PROD-STATUS (AD=OI)
    / 'TYPE       :' PROD-TYPE (AD=OI)
    / 'BRAND      :' PROD-BRAND (AD=OI)
    / 'DEPT/CLASS :' PROD-DEPT (AD=OI) '/' PROD-CLASS (AD=OI)
    / 'COLOR/SIZE :' PROD-COLOR (AD=OI) '/' PROD-SIZE (AD=OI)
    / 'COST       :' PROD-BASE-COST (AD=OI)
    / 'PRICE      :' PROD-BASE-PRICE (AD=OI)
    / 'INTRO DATE :' PROD-INTRO-DATE (AD=OI)
    / 'WEB        :' PROD-WEB-ENABLED (AD=OI)
    / 'PF3=RETURN'
*
END-SUBROUTINE
*
END
